export const KNOWLEDGE_CATS = [{"id":"teoriprovene","icon":"📝","color":"#1d6feb","names":{"no":"Teoriprøver","en":"Theory tests","ar":"الاختبارات النظرية","pl":"Egzaminy teoretyczne"},"intros":{"no":"Alt om teoriprøven — hvem som kan ta den, hva den inneholder, krav til bestått og vanlige feil.","en":"Everything about the theory test — who can take it, what it covers, pass requirements and common mistakes.","ar":"كل شيء عن الاختبار النظري — من يمكنه أخذه وما يغطيه ومتطلبات النجاح والأخطاء الشائعة.","pl":"Wszystko o egzaminie teoretycznym — kto może go zdawać, co obejmuje, wymagania do zdania i typowe błędy."},"faqs":[{"q":{"no":"Hva er teoriprøven og hvem tar den?","en":"What is the theory test and who takes it?","ar":"ما هو الاختبار النظري ومن يأخذه؟","pl":"Czym jest egzamin teoretyczny i kto go zdaje?"},"a":{"no":"Teoriprøven er en obligatorisk prøve som må bestås før du kan ta oppkjøring til de fleste førerkortklasser i Norge. Den tester din kunnskap om trafikkregler, trafikksikkerhet, kjøretøyteknikk og atferd i trafikken. Prøven avlegges digitalt hos Statens vegvesen og tar ca. 30–45 minutter.","en":"The theory test is a mandatory exam that must be passed before you can take the practical driving test for most driving licence classes in Norway. It tests your knowledge of traffic rules, road safety, vehicle technology and road behaviour. The test is taken digitally at the Norwegian Public Roads Administration and takes approximately 30-45 minutes.","ar":"الاختبار النظري هو امتحان إلزامي يجب اجتيازه قبل تقديم اختبار القيادة العملي لمعظم فئات رخص القيادة في النرويج. يختبر معرفتك بقواعد السير وسلامة الطرق وتقنيات المركبات والسلوك في المرور. يُجرى الاختبار رقمياً في إدارة الطرق العامة النرويجية ويستغرق نحو 30-45 دقيقة.","pl":"Egzamin teoretyczny jest obowiązkowym testem, który należy zdać przed przystąpieniem do praktycznego egzaminu na prawo jazdy dla większości kategorii w Norwegii. Sprawdza wiedzę z przepisów ruchu drogowego, bezpieczeństwa, techniki pojazdu i zachowania na drodze. Test jest przeprowadzany cyfrowo w Zarządzie Dróg Publicznych i trwa ok. 30-45 minut."},"details":{"no":[{"title":"Hvem kan ta teoriprøven?","items":["Alle som har nådd minstealder for gjeldende klasse","Klasse B: 17 år (med foresattes samtykke) eller 18 år","Klasse C: 18 år (21 år for fullt C-kort)","Klasse D: 21 år","Du trenger ikke ha kjøretimer for å ta teoriprøven"]},{"title":"Hva koster prøven?","items":["Klasse B: ca. 465 kr (2024)","Klasse C/CE: ca. 465 kr","Nye forsøk: samme pris","Betales ved booking hos Statens vegvesen"]}]},"tips":{"no":"Teoriprøven kan tas på norsk, samisk, engelsk og en rekke andre språk. Book time på Statens vegvesen sine nettsider eller i deres app.","en":"The theory test can be taken in Norwegian, Sami, English and several other languages. Book a time at the Roads Administration website or app.","ar":"يمكن أخذ الاختبار النظري بالنرويجية والسامية والإنجليزية وعدة لغات أخرى. احجز موعداً عبر موقع إدارة الطرق أو تطبيقها.","pl":"Egzamin można zdawać po norwesku, w języku Sami, angielskim i kilku innych. Zarezerwuj termin na stronie Zarządu Dróg."},"sources":["Statens vegvesen","Vegtrafikkloven § 24","Trafikkopplæringsforskriften"],"quiz":{"q":{"no":"Hva er minste alder for å ta teoriprøven til klasse B?","en":"What is the minimum age to take the class B theory test?","ar":"ما الحد الأدنى للسن لأخذ الاختبار النظري للفئة B؟","pl":"Jaki jest minimalny wiek do zdawania egzaminu teoretycznego kategorii B?"},"opts":{"no":["15 år","16 år","17 år","18 år"],"en":["15 years","16 years","17 years","18 years"],"ar":["15 عاماً","16 عاماً","17 عاماً","18 عاماً"],"pl":["15 lat","16 lat","17 lat","18 lat"]},"c":2,"expl":{"no":"Minste alder for teoriprøve klasse B er 17 år, men da kreves foresattes samtykke. Uten samtykke er aldersgrensen 18 år.","en":"The minimum age for the class B theory test is 17 years, but parental consent is required. Without consent the age limit is 18.","ar":"الحد الأدنى للسن في الاختبار النظري للفئة B هو 17 عاماً، لكن يُشترط موافقة ولي الأمر. بدون موافقة يكون الحد الأدنى 18 عاماً.","pl":"Minimalny wiek do egzaminu teoretycznego kategorii B to 17 lat, ale wymagana jest zgoda rodziców. Bez zgody limit wynosi 18 lat."}}},{"q":{"no":"Hva er kravet til å bestå teoriprøven?","en":"What is required to pass the theory test?","ar":"ما الذي يُشترط لاجتياز الاختبار النظري؟","pl":"Jakie są wymagania do zdania egzaminu teoretycznego?"},"a":{"no":"For å bestå teoriprøven til klasse B må du svare riktig på minst 85 av 100 spørsmål (85 %). For yrkessjåførklasser som C, CE og D er kravet 75 % — dvs. 22 av 30 riktige svar. Prøven er satt ut fra offisielle læremål godkjent av Statens vegvesen. Spørsmålene er flervalgsspørsmål med 4 svaralternativer.","en":"To pass the theory test for class B you must answer at least 85 out of 100 questions correctly (85%). For commercial driver classes such as C, CE and D the requirement is 75% — i.e. 22 out of 30 correct answers. The test is based on official learning objectives approved by the Roads Administration. Questions are multiple choice with 4 options.","ar":"لاجتياز الاختبار النظري للفئة B يجب الإجابة الصحيحة على 85 من أصل 100 سؤال على الأقل (85٪). لفئات السائق المهني كـC وCE وD المتطلب 75٪ — أي 22 من 30 إجابة صحيحة. الاختبار مبني على أهداف تعليمية رسمية معتمدة من إدارة الطرق. الأسئلة متعددة الاختيارات بـ4 خيارات.","pl":"Aby zdać egzamin teoretyczny kategorii B, musisz poprawnie odpowiedzieć na co najmniej 85 ze 100 pytań (85%). Dla kategorii zawodowych C, CE i D wymóg to 75% — tj. 22 z 30 poprawnych odpowiedzi. Test oparty jest na oficjalnych celach edukacyjnych zatwierdzonych przez Zarząd Dróg. Pytania są wielokrotnego wyboru z 4 opcjami."},"table":{"headers":{"no":["Klasse","Antall spm","Krav til bestått","Tid"],"en":["Class","No. of questions","Pass requirement","Time"],"ar":["الفئة","عدد الأسئلة","متطلب النجاح","الوقت"],"pl":["Kategoria","Liczba pytań","Wymaganie do zdania","Czas"]},"rows":[["B","100","85 (85%)","45 min"],["C/CE","30","22 (75%)","30 min"],["D","30","22 (75%)","30 min"],["Taxi/Løyve","30","22 (75%)","45 min"]]},"tips":{"no":"Tips til teoriprøven: Øv med offisielle øvingsapper, les Regler for vegen grundig, og fokuser på trafikksituasjoner fremfor memorering.","en":"Theory test tips: Practice with official test apps, read the Road Rules thoroughly and focus on traffic situations rather than memorisation.","ar":"نصائح للاختبار النظري: تدرب بالتطبيقات الرسمية واقرأ قواعد السير بدقة وركز على المواقف المرورية بدلاً من الحفظ.","pl":"Wskazówki: Ćwicz z oficjalnymi aplikacjami, przeczytaj dokładnie Przepisy drogowe i skup się na sytuacjach drogowych zamiast na zapamiętywaniu."},"sources":["Statens vegvesen","Trafikkopplæringsforskriften §3"]},{"q":{"no":"Hva er de vanligste feilene på teoriprøven?","en":"What are the most common mistakes on the theory test?","ar":"ما أكثر الأخطاء شيوعاً في الاختبار النظري؟","pl":"Jakie są najczęstsze błędy na egzaminie teoretycznym?"},"a":{"no":"De vanligste feilene på teoriprøven er: (1) Vikeplikt i kryss — mange er usikre på hvem som har vikeplikt for hvem. (2) Fartsregler — spesielt på motorvei og i tettbygd strøk. (3) Lyssignaler og skilt — misforståelse av skiltenes betydning. (4) Avstand til forankjørende — undervurderer nødvendig sikkerhetssone. (5) Trafikkregler om bord i kjøretøyet — bilbelte, bruk av telefon. Disse temaene bør du bruke ekstra tid på under øvingen.","en":"The most common mistakes on the theory test are: (1) Right of way at junctions — many are unsure who gives way to whom. (2) Speed rules — especially on motorways and in built-up areas. (3) Traffic lights and signs — misunderstanding sign meanings. (4) Following distance — underestimating the required safety gap. (5) In-vehicle traffic rules — seatbelt, mobile phone use. Spend extra time on these topics when studying.","ar":"أكثر الأخطاء شيوعاً في الاختبار النظري: (1) الأولوية في التقاطعات — كثيرون غير متأكدين من الأولويات. (2) قواعد السرعة — خاصةً على الطرق السريعة وفي المناطق العمرانية. (3) إشارات المرور واللافتات — سوء فهم معاني اللافتات. (4) مسافة المتابعة — التقليل من منطقة الأمان اللازمة. (5) قواعد السير داخل المركبة — حزام الأمان والهاتف. خصص وقتاً إضافياً لهذه الموضوعات أثناء الدراسة.","pl":"Najczęstsze błędy na egzaminie: (1) Pierwszeństwo na skrzyżowaniach. (2) Zasady prędkości — szczególnie na autostradach. (3) Sygnalizacja i znaki. (4) Odległość od poprzedzającego pojazdu. (5) Przepisy dotyczące pasażerów — pasy, telefon. Poświęć dodatkowy czas na te tematy."},"tips":{"no":"Vanlige feil ved vikeplikt: Husk at kjøretøy på overordnet vei alltid har forkjørsrett. Gangfelt gir IKKE deg rett til å kjøre uten å vike for fotgjengere.","en":"Common right-of-way mistakes: Remember that vehicles on a priority road always have right of way. Zebra crossings do NOT give you the right to drive without giving way to pedestrians.","ar":"أخطاء شائعة في الأولوية: تذكر أن المركبات على الطريق ذي الأولوية لها دائماً حق المرور. ممرات المشاة لا تمنحك الحق في القيادة دون إعطاء الأولوية للمشاة.","pl":"Częste błędy przy pierwszeństwie: Pamiętaj, że pojazdy na drodze z pierwszeństwem zawsze mają pierwszeństwo. Przejście dla pieszych NIE daje ci prawa jazdy bez ustąpienia pieszym."},"sources":["Vegtrafikkloven §9","Skiltforskriften"]}]},{"id":"forerkortklasser","icon":"🚗","color":"#1a9e52","names":{"no":"Førerkortklasser","en":"Driving licence classes","ar":"فئات رخصة القيادة","pl":"Kategorie prawa jazdy"},"intros":{"no":"Komplett oversikt over alle førerkortklasser i Norge — fra moped til tungt vogntog.","en":"Complete overview of all driving licence classes in Norway — from moped to heavy combination vehicle.","ar":"نظرة عامة شاملة على جميع فئات رخصة القيادة في النرويج — من الدراجة البخارية إلى المركبات الثقيلة.","pl":"Kompletny przegląd wszystkich kategorii prawa jazdy w Norwegii — od motoroweru do ciężkich zestawów."},"faqs":[{"q":{"no":"Hva er forskjellen mellom klasse C og CE?","en":"What is the difference between class C and CE?","ar":"ما الفرق بين الفئة C وCE؟","pl":"Jaka jest różnica między kategorią C a CE?"},"a":{"no":"Klasse C gir rett til å kjøre lastebil med totalvekt over 3 500 kg, med eller uten tilhenger med totalvekt under 750 kg. Klasse CE gir i tillegg rett til å koble til tyngre tilhenger — slik at du kan kjøre vogntog (lastebil + semitrailer). CE krever at du allerede har klasse C. Begge krever at du har hatt klasse B i minst 1 år.","en":"Class C gives the right to drive a lorry with a total weight over 3,500 kg, with or without a trailer with a total weight under 750 kg. Class CE additionally gives the right to attach a heavier trailer — allowing you to drive a combination vehicle (lorry + semitrailer). CE requires that you already hold class C. Both require that you have held class B for at least 1 year.","ar":"الفئة C تمنح الحق في قيادة شاحنة بوزن إجمالي يتجاوز 3500 كغ، مع مقطورة أو بدونها بوزن إجمالي أقل من 750 كغ. الفئة CE تمنح إضافةً حق ربط مقطورة أثقل — مما يتيح قيادة مجموعة مركبات (شاحنة + نصف مقطورة). CE تستلزم امتلاك الفئة C مسبقاً. كلاهما يستلزم حيازة الفئة B لمدة سنة على الأقل.","pl":"Kategoria C uprawnia do jazdy ciężarówką o DMC powyżej 3500 kg, z przyczepą lub bez (DMC poniżej 750 kg). Kategoria CE uprawnia dodatkowo do dołączenia cięższej przyczepy — czyli do prowadzenia zestawu (ciężarówka + naczepa). CE wymaga posiadania kategorii C. Obie wymagają posiadania kategorii B przez co najmniej 1 rok."},"table":{"headers":{"no":["Klasse","Kjøretøy","Maks vekt","Minstealder"],"en":["Class","Vehicle","Max weight","Min age"],"ar":["الفئة","المركبة","الوزن الأقصى","الحد الأدنى للسن"],"pl":["Kategoria","Pojazd","Maks. masa","Min. wiek"]},"rows":[["B","Personbil, varebil","3 500 kg","18 (17 øvelse)"],["B96","Bil m/tilhenger","4 250 kg","18"],["BE","Bil m/tung tilhenger","u/begrensning","18"],["C1","Lett lastebil","7 500 kg","18"],["C","Lastebil","> 3 500 kg","21 (18 m/kode)"],["CE","Vogntog (lastebil+henger)","u/begrensning","21"],["D","Buss (rute)","> 9 seter","21 (24 rute)"],["T","Traktor","u/begrensning","16"]]},"tips":{"no":"YSK (Yrkeskompetansebevis) — fra 2009 krever alle som kjører C/CE eller D profesjonelt et 35 timers kompetansebevis som fornyes hvert 5. år.","en":"YSK (Vocational Competence Certificate) — since 2009 all professional C/CE or D drivers require a 35-hour competence certificate renewed every 5 years.","ar":"YSK (شهادة الكفاءة المهنية) — منذ 2009 يحتاج جميع سائقي C/CE أو D المهنيين إلى شهادة 35 ساعة تُجدد كل 5 سنوات.","pl":"YSK (Zaświadczenie o kwalifikacjach zawodowych) — od 2009 r. wszyscy zawodowi kierowcy C/CE lub D potrzebują 35-godzinnego certyfikatu odnawianego co 5 lat."},"sources":["Vegtrafikkloven § 24","Trafikkopplæringsforskriften","EU-direktiv 2006/126/EF"]},{"q":{"no":"Hva er YSK og hvem trenger det?","en":"What is YSK and who needs it?","ar":"ما هو YSK ومن يحتاجه؟","pl":"Co to jest YSK i kto go potrzebuje?"},"a":{"no":"YSK (Yrkeskompetansebevis) er et obligatorisk kompetansebevis for sjåfører som kjører gods- eller persontransport profesjonelt. Det er hjemlet i EU-direktiv 2003/59/EF og ble innført i Norge i 2008–2009. Beviset krever et 35-timers opplæringskurs, og fornyes hvert 5. år med 35 nye timer. Alle som kjører lastebil (C/CE) eller buss (D) i yrkesmessig godtgjort kjøring MÅ ha YSK. Privat kjøring og kjøring for eget bruk er unntatt.","en":"YSK (Vocational Competence Certificate) is a mandatory competence certificate for drivers who carry out goods or passenger transport professionally. It is based on EU Directive 2003/59/EC and was introduced in Norway in 2008-2009. The certificate requires a 35-hour training course and is renewed every 5 years with 35 new hours. All drivers of lorries (C/CE) or buses (D) in professionally remunerated driving MUST have YSK. Private driving and driving for own use is exempt.","ar":"YSK (شهادة الكفاءة المهنية) هي شهادة كفاءة إلزامية للسائقين الذين يقومون بنقل البضائع أو الركاب مهنياً. مستندة إلى توجيه الاتحاد الأوروبي 2003/59/EC وأُدخلت في النرويج عامَي 2008-2009. الشهادة تستلزم دورة تدريبية 35 ساعة وتُجدد كل 5 سنوات بـ35 ساعة جديدة. جميع سائقي الشاحنات (C/CE) أو الحافلات (D) في القيادة المأجورة مهنياً يجب أن يمتلكوا YSK. القيادة الخاصة والقيادة للاستخدام الشخصي معفاة.","pl":"YSK (Zaświadczenie o kwalifikacjach zawodowych) to obowiązkowy certyfikat dla kierowców wykonujących zawodowy transport towarów lub osób. Oparty na Dyrektywie UE 2003/59/WE, wprowadzony w Norwegii w latach 2008-2009. Certyfikat wymaga 35-godzinnego kursu szkoleniowego i jest odnawiany co 5 lat. Wszyscy kierowcy ciężarówek (C/CE) lub autobusów (D) w zarobkowym transporcie MUSZĄ mieć YSK."},"tips":{"no":"YSK-kurset kan deles opp over 5 år (7 timer per år) eller tas samlet. De 35 timene kan ikke erstattes av andre kurs.","en":"The YSK course can be split over 5 years (7 hours per year) or taken all at once. The 35 hours cannot be replaced by other courses.","ar":"يمكن تقسيم دورة YSK على 5 سنوات (7 ساعات في السنة) أو أخذها دفعة واحدة. لا يمكن استبدال الـ35 ساعة بدورات أخرى.","pl":"Kurs YSK można podzielić na 5 lat (7 godzin rocznie) lub odbyć jednorazowo. 35 godzin nie można zastąpić innymi kursami."},"sources":["EU-direktiv 2003/59/EF","Yrkestransportforskriften § 5","Statens vegvesen"],"quiz":{"q":{"no":"Hva er minste antall timer i YSK-kurset?","en":"What is the minimum number of hours in the YSK course?","ar":"ما الحد الأدنى لساعات دورة YSK؟","pl":"Jaka jest minimalna liczba godzin kursu YSK?"},"opts":{"no":["20 timer","25 timer","35 timer","45 timer"],"en":["20 hours","25 hours","35 hours","45 hours"],"ar":["20 ساعة","25 ساعة","35 ساعة","45 ساعة"],"pl":["20 godzin","25 godzin","35 godzin","45 godzin"]},"c":2,"expl":{"no":"YSK-kurset er på 35 timer og fornyes hvert 5. år. Uten gyldig YSK er det ulovlig å kjøre godstransport eller persontransport mot betaling.","en":"The YSK course is 35 hours and renewed every 5 years. Without valid YSK it is illegal to drive goods or passenger transport for payment.","ar":"دورة YSK مدتها 35 ساعة وتُجدد كل 5 سنوات. بدون YSK صالح يكون القيادة في نقل البضائع أو الركاب مقابل أجر غير قانونية.","pl":"Kurs YSK trwa 35 godzin i jest odnawiany co 5 lat. Bez ważnego YSK kierowanie w transporcie towarowym lub osobowym za wynagrodzeniem jest nielegalne."}}}]},{"id":"kjore_hviletid","icon":"⏱️","color":"#c2410c","names":{"no":"Kjøre- og hviletid","en":"Driving and rest times","ar":"أوقات القيادة والراحة","pl":"Czas jazdy i odpoczynku"},"intros":{"no":"Reglene om kjøre- og hviletid er blant de viktigste i yrkestransport. De er regulert av EU-forordning 561/2006 og gjelder for alle som kjører lastebil eller buss i yrkesmessig transport.","en":"Driving and rest time rules are among the most important in commercial transport. They are governed by EU Regulation 561/2006 and apply to all professional lorry or bus drivers.","ar":"قواعد أوقات القيادة والراحة من أهم القواعد في النقل المهني. تحكمها لائحة الاتحاد الأوروبي 561/2006 وتنطبق على جميع سائقي الشاحنات أو الحافلات المهنيين.","pl":"Przepisy dotyczące czasu jazdy i odpoczynku należą do najważniejszych w transporcie zawodowym. Regulowane przez Rozporządzenie UE 561/2006 i dotyczą wszystkich zawodowych kierowców ciężarówek lub autobusów."},"faqs":[{"q":{"no":"Hva er reglene for daglig kjøretid?","en":"What are the rules for daily driving time?","ar":"ما القواعد المتعلقة بوقت القيادة اليومي؟","pl":"Jakie są zasady dotyczące dziennego czasu jazdy?"},"a":{"no":"Maksimal daglig kjøretid er 9 timer. Dette kan utvides til 10 timer maksimalt 2 ganger per uke. Kjøretiden er den tid hjulene ruller — pauser, lossing, lasting og ventetid regnes ikke som kjøretid. Etter 4,5 timers sammenhengende kjøring må du ta en pause på minst 45 minutter (kan deles i 15 + 30 minutter i den rekkefølgen). Daglig kjøretid tilbakestilles etter 11 timers hvile.","en":"Maximum daily driving time is 9 hours. This can be extended to 10 hours a maximum of 2 times per week. Driving time is when the wheels are turning — breaks, unloading, loading and waiting time do not count as driving time. After 4.5 hours of continuous driving you must take a break of at least 45 minutes (can be split as 15 + 30 minutes in that order). Daily driving time resets after 11 hours of rest.","ar":"الحد الأقصى لوقت القيادة اليومي هو 9 ساعات. يمكن تمديده إلى 10 ساعات مرتين كحد أقصى في الأسبوع. وقت القيادة هو الوقت الذي تدور فيه العجلات — فترات الراحة والتفريغ والتحميل ووقت الانتظار لا تُحتسب وقت قيادة. بعد 4.5 ساعة من القيادة المتواصلة يجب أخذ استراحة لا تقل عن 45 دقيقة (يمكن تقسيمها إلى 15 + 30 دقيقة بهذا الترتيب). وقت القيادة اليومي يُعاد تعيينه بعد 11 ساعة من الراحة.","pl":"Maksymalny dzienny czas jazdy wynosi 9 godzin. Może być przedłużony do 10 godzin maksymalnie 2 razy w tygodniu. Czas jazdy to gdy koła się obracają — przerwy, rozładunek, załadunek i oczekiwanie nie liczą się jako czas jazdy. Po 4,5 godzinach nieprzerwanej jazdy należy zrobić przerwę co najmniej 45 minut (można podzielić 15+30 minut w tej kolejności). Dzienny czas jazdy resetuje się po 11 godzinach odpoczynku."},"table":{"headers":{"no":["Regel","Normalt","Utvidet","Maks per uke"],"en":["Rule","Normal","Extended","Max per week"],"ar":["القاعدة","عادي","ممتد","الحد الأقصى أسبوعياً"],"pl":["Zasada","Normalnie","Rozszerzone","Maks. w tygodniu"]},"rows":[["Daglig kjøretid","9 timer","10 timer (2×/uke)","56 timer"],["Pause etter 4,5t","45 min","–","–"],["Daglig hvile","11 timer","9 timer (3×/uke)","–"],["Ukentlig hvile","45 timer","24 timer (komp.)","–"],["Ukentlig kjøretid","–","–","56 timer"],["2-ukers kjøretid","–","–","90 timer"]]},"warnings":{"no":"Brudd på kjøre-/hviletidsreglene kan medføre bøter på opptil 10 000 kr for sjåfør og mye mer for transportselskapet. Gjentatte brudd kan føre til tap av løyvet.","en":"Violations of driving/rest time rules can result in fines of up to NOK 10,000 for the driver and much more for the transport company. Repeated violations can lead to loss of the licence.","ar":"انتهاكات قواعد أوقات القيادة/الراحة قد تؤدي إلى غرامات تصل إلى 10000 كرونة للسائق وأكثر بكثير لشركة النقل. الانتهاكات المتكررة قد تؤدي إلى فقدان الرخصة.","pl":"Naruszenia zasad czasu jazdy/odpoczynku mogą skutkować grzywnami do 10 000 NOK dla kierowcy i znacznie więcej dla firmy transportowej. Powtarzające się naruszenia mogą prowadzić do utraty licencji."},"sources":["EU-forordning 561/2006","Forskrift om kjøre- og hviletid"]},{"q":{"no":"Hva er reglene for ukentlig hvile?","en":"What are the rules for weekly rest?","ar":"ما القواعد المتعلقة بالراحة الأسبوعية؟","pl":"Jakie są zasady dotyczące tygodniowego odpoczynku?"},"a":{"no":"Sjåfører har krav på ukentlig hvile etter maksimalt 6 daglige kjøreperioder. Normal ukentlig hvile er 45 sammenhengende timer. Redusert ukentlig hvile på minimum 24 timer er tillatt, men kuttet tid (21 timer) SKAL kompenseres fullt ut innen 3 uker. Kompensasjonen legges til en sammenhengende hvileperiode på minst 9 timer. Siden 2020 er det forbudt å ta ukentlig hvile i lastebilhytten (cab rest) i EU/EØS.","en":"Drivers are entitled to weekly rest after a maximum of 6 daily driving periods. Normal weekly rest is 45 consecutive hours. Reduced weekly rest of minimum 24 hours is permitted, but the cut time (21 hours) MUST be fully compensated within 3 weeks. The compensation is attached to a continuous rest period of at least 9 hours. Since 2020, taking weekly rest in the lorry cab has been prohibited in the EU/EEA.","ar":"يحق للسائقين الحصول على راحة أسبوعية بعد 6 فترات قيادة يومية كحد أقصى. الراحة الأسبوعية العادية هي 45 ساعة متواصلة. الراحة الأسبوعية المخفضة بحد أدنى 24 ساعة مسموحة، لكن الوقت المقطوع (21 ساعة) يجب تعويضه بالكامل خلال 3 أسابيع. التعويض يُضاف لفترة راحة متواصلة لا تقل عن 9 ساعات. منذ 2020 حُظر أخذ الراحة الأسبوعية في مقصورة الشاحنة في الاتحاد/المنطقة الأوروبية.","pl":"Kierowcy mają prawo do tygodniowego odpoczynku po maksymalnie 6 dziennych okresach jazdy. Normalny tygodniowy odpoczynek to 45 kolejnych godzin. Skrócony tygodniowy odpoczynek wynoszący minimum 24 godziny jest dozwolony, ale skrócony czas (21 godzin) MUSI być w pełni zrekompensowany w ciągu 3 tygodni. Od 2020 r. zakazane jest odbywanie tygodniowego odpoczynku w kabinie ciężarówki w UE/EOG."},"tips":{"no":"Husk: Ukentlig hvile beregnes fra slutten av siste daglige hvile. Kalenderuke spiller ingen rolle — det er de siste 6 kjøredagene som teller.","en":"Remember: Weekly rest is calculated from the end of the last daily rest. Calendar week is irrelevant — the last 6 driving days are what count.","ar":"تذكر: تُحسب الراحة الأسبوعية من نهاية آخر راحة يومية. الأسبوع التقويمي غير مهم — آخر 6 أيام قيادة هي ما يُحتسب.","pl":"Pamiętaj: Tygodniowy odpoczynek jest liczony od końca ostatniego dziennego odpoczynku. Tydzień kalendarzowy nie ma znaczenia — liczy się 6 ostatnich dni jazdy."},"sources":["EU-forordning 561/2006, art. 8","Kommisjonsforordning 2020/1054"]}]},{"id":"tachograf","icon":"📡","color":"#7c3aed","names":{"no":"Tachograf (fartsskriver)","en":"Tachograph","ar":"جهاز التسجيل (التاكوغراف)","pl":"Tachograf"},"intros":{"no":"Tachografen er det elektroniske øyet i lastebilen. Den registrerer kjøretid, hastighet, hvile og aktiviteter. Riktig bruk er lovpålagt og kontrolleres strengt.","en":"The tachograph is the electronic eye in the lorry. It records driving time, speed, rest and activities. Correct use is legally required and strictly monitored.","ar":"التاكوغراف هو العين الإلكترونية في الشاحنة. يسجل وقت القيادة والسرعة والراحة والأنشطة. الاستخدام الصحيح إلزامي قانونياً ويُراقب بصرامة.","pl":"Tachograf to elektroniczne oko w ciężarówce. Rejestruje czas jazdy, prędkość, odpoczynek i aktywności. Prawidłowe użytkowanie jest wymagane przez prawo i ściśle kontrolowane."},"faqs":[{"q":{"no":"Hva er digital og analog tachograf?","en":"What is a digital and analogue tachograph?","ar":"ما هو التاكوغراف الرقمي والتناظري؟","pl":"Czym jest cyfrowy i analogowy tachograf?"},"a":{"no":"Analog tachograf bruker voksdisker (diagramskiver) som roterer og registrerer kjøring mekanisk. Brukes i eldre kjøretøy. Digital tachograf (innført fra 2006) bruker en smartkortteknologi — sjåføren setter inn sitt personlige sjåførkort, og all aktivitet lagres elektronisk. Smart tachograf (gen. 2, fra 2019) overfører automatisk data og kommuniserer med GPS og kontrollmyndigheter. Fra 2023 er smart tachograf gen. 2 obligatorisk i nye kjøretøy.","en":"An analogue tachograph uses wax discs (chart discs) that rotate and record driving mechanically. Used in older vehicles. A digital tachograph (introduced from 2006) uses smart card technology — the driver inserts their personal driver card and all activity is stored electronically. Smart tachograph (gen. 2, from 2019) transmits data automatically and communicates with GPS and inspection authorities. From 2023, smart tachograph gen. 2 is mandatory in new vehicles.","ar":"التاكوغراف التناظري يستخدم أقراص شمعية (أقراص رسم بياني) تدور وتسجل القيادة ميكانيكياً. يُستخدم في المركبات القديمة. التاكوغراف الرقمي (أُدخل منذ 2006) يستخدم تقنية البطاقة الذكية — يُدخل السائق بطاقته الشخصية وتُخزّن جميع الأنشطة إلكترونياً. التاكوغراف الذكي (الجيل 2، منذ 2019) ينقل البيانات تلقائياً ويتواصل مع GPS وجهات التفتيش. منذ 2023 أصبح التاكوغراف الذكي الجيل 2 إلزامياً في المركبات الجديدة.","pl":"Analogowy tachograf używa woskowych krążków (tarcz wykresowych), które obracają się i rejestrują jazdę mechanicznie. Stosowany w starszych pojazdach. Cyfrowy tachograf (od 2006) używa technologii kart chipowych — kierowca wkłada swoją kartę kierowcy i cała aktywność jest przechowywana elektronicznie. Inteligentny tachograf (gen. 2, od 2019) automatycznie przesyła dane i komunikuje się z GPS. Od 2023 r. inteligentny tachograf gen. 2 jest obowiązkowy w nowych pojazdach."},"tips":{"no":"Viktig: Sjåfør plikter å starte tachografen ved kjørestart og sette riktig aktivitetsmodus (kjøring/pause/hvile/annet arbeid). Glem aldri å ta med sjåførkort!","en":"Important: The driver must start the tachograph at the start of driving and set the correct activity mode (driving/break/rest/other work). Never forget your driver card!","ar":"مهم: يجب على السائق تشغيل التاكوغراف عند بدء القيادة وضبط وضع النشاط الصحيح (قيادة/استراحة/راحة/عمل آخر). لا تنس بطاقة السائق أبداً!","pl":"Ważne: Kierowca musi uruchomić tachograf przy rozpoczęciu jazdy i ustawić właściwy tryb aktywności. Nigdy nie zapomnij karty kierowcy!"},"sources":["EU-forordning 165/2014","EU-forordning 561/2006 art. 33"]}]},{"id":"lastsikring","icon":"📦","color":"#d4a017","names":{"no":"Lastsikring og vekt","en":"Load securing and weight","ar":"تأمين الحمولة والوزن","pl":"Zabezpieczenie ładunku i masa"},"intros":{"no":"Korrekt lastsikring redder liv. Feilsikret last er en av de vanligste årsakene til alvorlige trafikkulykker med tunge kjøretøy.","en":"Correct load securing saves lives. Incorrectly secured loads are one of the most common causes of serious traffic accidents involving heavy vehicles.","ar":"تأمين الحمولة الصحيح ينقذ الأرواح. الحمولة غير المؤمنة بشكل صحيح من أكثر أسباب حوادث السير الخطيرة شيوعاً مع المركبات الثقيلة.","pl":"Prawidłowe zabezpieczenie ładunku ratuje życie. Nieprawidłowo zabezpieczony ładunek jest jedną z najczęstszych przyczyn poważnych wypadków drogowych."},"faqs":[{"q":{"no":"Hva er reglene for lastsikring i Norge?","en":"What are the load securing rules in Norway?","ar":"ما قواعد تأمين الحمولة في النرويج؟","pl":"Jakie są zasady zabezpieczania ładunku w Norwegii?"},"a":{"no":"Lastsikringsreglene er hjemlet i vegtrafikkloven § 3 og forskrift om bruk av kjøretøy. Godset skal sikres slik at det ikke kan forskyve seg, falle av eller forårsake fare under kjøring. Grunnprinsippene er: (1) Direkte sikring — godset holdes på plass av stropper, kjettinger eller bolter. (2) Friksjonssikring — godset holdes på plass ved hjelp av friksjon mellom last og lasteflate. Minimum friksjonsfaktor: 0,3 for trematerialer mot trematerialer, 0,5 for gummi mot gummi. Alle stropper skal ha godkjent merking (CE-merking) og angitt stramningskraft (STF).","en":"Load securing rules are based in Road Traffic Act §3 and vehicle use regulations. Cargo must be secured so that it cannot shift, fall off or cause hazard during driving. Basic principles: (1) Direct securing — cargo held in place by straps, chains or bolts. (2) Friction securing — cargo held in place by friction between load and load surface. Minimum friction factor: 0.3 for wood against wood, 0.5 for rubber against rubber. All straps must have approved marking (CE marking) and stated pre-tension force (STF).","ar":"قواعد تأمين الحمولة مستندة إلى المادة 3 من قانون السير ولوائح استخدام المركبات. يجب تأمين البضائع بحيث لا تتزحزح أو تسقط أو تسبب خطراً أثناء القيادة. المبادئ الأساسية: (1) التأمين المباشر — الحمولة في مكانها بواسطة أحزمة أو سلاسل أو مسامير. (2) تأمين الاحتكاك — الحمولة في مكانها بالاحتكاك بين الحمولة وسطح التحميل. عامل الاحتكاك الأدنى: 0.3 للخشب على خشب، 0.5 للمطاط على مطاط. جميع الأحزمة يجب أن تحمل علامة معتمدة (CE) وقوة شد مُحددة (STF).","pl":"Przepisy dot. zabezpieczania ładunku wynikają z §3 Kodeksu drogowego i przepisów o użytkowaniu pojazdów. Ładunek musi być zabezpieczony tak, aby nie przesuwał się, nie spadał i nie powodował zagrożenia. Podstawowe zasady: (1) Mocowanie bezpośrednie — ładunek utrzymywany przez pasy, łańcuchy lub śruby. (2) Mocowanie tarciowe — ładunek utrzymywany przez tarcie między ładunkiem a podłogą. Minimalny współczynnik tarcia: 0.3 dla drewna na drewno, 0.5 guma na gumę."},"table":{"headers":{"no":["Retning","Krav til sikringskraft"],"en":["Direction","Required securing force"],"ar":["الاتجاه","قوة التأمين المطلوبة"],"pl":["Kierunek","Wymagana siła mocowania"]},"rows":[["Fremover","0,8 × godsets vekt (N)"],["Bakover","0,5 × godsets vekt (N)"],["Sidelengs","0,5 × godsets vekt (N)"]]},"tips":{"no":"Tips: Vær alltid sikker på at lasten er jevnt fordelt. Unngå overlasting — sjekk aksellastene med vektbro ved behov.","en":"Tips: Always make sure the load is evenly distributed. Avoid overloading — check axle loads at a weigh station if necessary.","ar":"نصائح: تأكد دائماً من توزيع الحمولة بالتساوي. تجنب الإثقال الزائد — افحص أحمال المحور في محطة الوزن عند الحاجة.","pl":"Wskazówka: Zawsze upewnij się, że ładunek jest równomiernie rozłożony. Unikaj przeciążenia — sprawdź obciążenia osi na wadze."},"sources":["Vegtrafikkloven § 3","Forskrift om bruk av kjøretøy","NS-EN 12195 (lastsikringsstandard)"]}]},{"id":"adr","icon":"☢️","color":"#cf222e","names":{"no":"ADR — Farlig gods","en":"ADR — Dangerous goods","ar":"ADR — البضائع الخطرة","pl":"ADR — Towary niebezpieczne"},"intros":{"no":"ADR (Accord européen relatif au transport international des marchandises Dangereuses par Route) er den europeiske konvensjonen for transport av farlig gods på veg. Norsk implementering gjennom ADR-forskriften.","en":"ADR (Accord européen relatif au transport international des marchandises Dangereuses par Route) is the European convention for transport of dangerous goods by road. Norwegian implementation through the ADR regulations.","ar":"ADR هي الاتفاقية الأوروبية لنقل البضائع الخطرة براً. التطبيق النرويجي عبر لوائح ADR.","pl":"ADR to Europejska umowa dotycząca międzynarodowego przewozu towarów niebezpiecznych drogami. Implementacja norweska przez przepisy ADR."},"faqs":[{"q":{"no":"Hva er de 9 klassene i ADR?","en":"What are the 9 classes in ADR?","ar":"ما الفئات التسع في ADR؟","pl":"Jakie są 9 klas ADR?"},"a":{"no":"ADR deler farlig gods i 9 hovedklasser basert på farens art. Det er svært viktig å kjenne disse, da feil klassifisering kan ha katastrofale konsekvenser.","en":"ADR divides dangerous goods into 9 main classes based on the nature of the hazard. Knowing these is extremely important, as incorrect classification can have catastrophic consequences.","ar":"تُقسّم ADR البضائع الخطرة إلى 9 فئات رئيسية بناءً على طبيعة الخطر. معرفة هذه الفئات بالغة الأهمية إذ قد يكون التصنيف الخاطئ كارثياً.","pl":"ADR dzieli towary niebezpieczne na 9 głównych klas w zależności od charakteru zagrożenia. Znajomość tych klas jest niezwykle ważna, gdyż błędna klasyfikacja może mieć katastrofalne skutki."},"table":{"headers":{"no":["Klasse","Beskrivelse","Eksempler"],"en":["Class","Description","Examples"],"ar":["الفئة","الوصف","أمثلة"],"pl":["Klasa","Opis","Przykłady"]},"rows":[["1","Eksplosive stoffer","Sprengstoff, fyrverkeri"],["2","Gasser","Propan, oksygen, aerosoler"],["3","Brannfarlige væsker","Bensin, diesel, acetone"],["4.1","Brannfarlige faste stoffer","Svovel, tennstikker"],["4.2","Selvantennende stoffer","Hvit fosfor"],["4.3","Stoffer som utvikler brennbar gass","Metallnatrium"],["5.1","Oksiderende stoffer","Natriumnitrat"],["5.2","Organiske peroksider","Benzoylperoksid"],["6.1","Giftige stoffer","Blyacetatt, cyanider"],["6.2","Smittefarlige stoffer","Medisinsk avfall, blodprøver"],["7","Radioaktive stoffer","Uranoksid, medisinsk Tc-99"],["8","Etsende stoffer","Saltsyre, natronlut"],["9","Diverse farlige stoffer","Litiumbatterier, asbestprodukter"]]},"tips":{"no":"Husk: Sjåfør plikter å bære ADR-kompetansebeviset og fremvise det ved kontroll. ADR-beviset er personlig og gyldig i 5 år.","en":"Remember: The driver must carry the ADR competence certificate and produce it at inspection. The ADR certificate is personal and valid for 5 years.","ar":"تذكر: يجب على السائق حمل شهادة كفاءة ADR وتقديمها عند التفتيش. شهادة ADR شخصية وصالحة لمدة 5 سنوات.","pl":"Pamiętaj: Kierowca musi nosić certyfikat kompetencji ADR i okazywać go podczas kontroli. Certyfikat jest osobisty i ważny przez 5 lat."},"sources":["ADR 2023","Forskrift om transport av farlig gods på veg"]}]},{"id":"hms","icon":"🦺","color":"#1a9e52","names":{"no":"HMS og arbeidsmiljø","en":"HSE and working environment","ar":"السلامة والصحة المهنية وبيئة العمل","pl":"BHP i środowisko pracy"},"intros":{"no":"HMS (Helse, Miljø og Sikkerhet) er lovpålagt for alle norske virksomheter. For transportbedrifter er HMS særlig viktig — sjåføren er alene bak rattet og i møte med farlige situasjoner.","en":"HSE (Health, Safety and Environment) is legally required for all Norwegian businesses. For transport companies, HSE is especially important — the driver is alone at the wheel facing hazardous situations.","ar":"السلامة والصحة المهنية وبيئة العمل إلزامية لجميع الشركات النرويجية. لشركات النقل تكتسب أهمية خاصة — السائق وحيد خلف المقود في مواجهة المواقف الخطرة.","pl":"BHP (Bezpieczeństwo, Higiena Pracy i Środowisko) jest wymagane przez prawo dla wszystkich norweskich firm. Dla firm transportowych BHP jest szczególnie ważne."},"faqs":[{"q":{"no":"Hva er internkontrollforskriften og hva krever den?","en":"What is the internal control regulation and what does it require?","ar":"ما هي لائحة الرقابة الداخلية وما متطلباتها؟","pl":"Czym jest rozporządzenie o kontroli wewnętrznej i czego wymaga?"},"a":{"no":"Internkontrollforskriften (IK-forskriften) pålegger alle norske virksomheter å jobbe systematisk med HMS. For transportbedrifter betyr dette: dokumenterte prosedyrer for sikker kjøring, rutiner for kjøretøykontroll, prosedyrer for lasting og lossing, opplæringsplaner, risikovurdering for kjøreruter og godstyper, avviksregistrering og beredskapsplan. Arbeidsgiver har det overordnede ansvaret, men ansatte plikter å medvirke.","en":"The Internal Control Regulation (IK regulations) requires all Norwegian businesses to work systematically with HSE. For transport companies this means: documented procedures for safe driving, vehicle inspection routines, loading and unloading procedures, training plans, risk assessment for routes and cargo types, incident recording and emergency plan. The employer has overall responsibility but employees have a duty to cooperate.","ar":"لائحة الرقابة الداخلية تُلزم جميع الشركات النرويجية بالعمل بشكل منهجي في السلامة والصحة المهنية. لشركات النقل يعني هذا: إجراءات موثقة للقيادة الآمنة وروتين فحص المركبات وإجراءات التحميل والتفريغ وخطط التدريب وتقييم المخاطر للمسارات وأنواع البضائع وتسجيل الانحرافات وخطة الطوارئ. صاحب العمل يتحمل المسؤولية الشاملة لكن الموظفين ملزمون بالمشاركة.","pl":"Rozporządzenie o kontroli wewnętrznej zobowiązuje wszystkie norweskie firmy do systematycznej pracy z BHP. Dla firm transportowych oznacza to: udokumentowane procedury bezpiecznej jazdy, rutyny kontroli pojazdów, procedury załadunku i rozładunku, plany szkoleń, ocenę ryzyka tras i typów ładunku."},"tips":{"no":"Sjåfører har rett til å nekte farlig arbeid! Arbeidsmiljøloven § 2-3 gir arbeidstaker rett til å stanse arbeidet ved alvorlig fare. Dette gjelder også for lastebilsjåfører.","en":"Drivers have the right to refuse dangerous work! Working Environment Act §2-3 gives employees the right to stop work in case of serious danger. This also applies to lorry drivers.","ar":"للسائقين الحق في رفض العمل الخطير! المادة 2-3 من قانون بيئة العمل تمنح الموظفين الحق في إيقاف العمل عند وجود خطر جسيم. ينطبق هذا أيضاً على سائقي الشاحنات.","pl":"Kierowcy mają prawo odmówić niebezpiecznej pracy! §2-3 Ustawy o środowisku pracy daje pracownikom prawo do zatrzymania pracy w przypadku poważnego zagrożenia."},"sources":["Internkontrollforskriften","Arbeidsmiljøloven §§ 2-1, 2-3, 4-4"]}]},{"id":"trafikksikkerhet","icon":"🔰","color":"#06b6d4","names":{"no":"Trafikksikkerhet","en":"Road safety","ar":"سلامة السير","pl":"Bezpieczeństwo ruchu drogowego"},"intros":{"no":"Trafikksikkerhet handler om å forebygge ulykker og redde liv. Norge har som mål null drepte i trafikken (Nullvisjonen). Kunnskap om risikofaktorer er nøkkelen.","en":"Road safety is about preventing accidents and saving lives. Norway has the goal of zero deaths in traffic (Zero Vision). Knowledge of risk factors is the key.","ar":"سلامة السير تتعلق بمنع الحوادث وإنقاذ الأرواح. النرويج لديها هدف صفر وفيات في السير (الرؤية الصفرية). معرفة عوامل الخطر هي المفتاح.","pl":"Bezpieczeństwo ruchu drogowego dotyczy zapobiegania wypadkom i ratowania życia. Norwegia ma cel zerowej liczby ofiar śmiertelnych (Zerowa wizja). Wiedza o czynnikach ryzyka jest kluczem."},"faqs":[{"q":{"no":"Hva er de vanligste årsakene til trafikkulykker i Norge?","en":"What are the most common causes of traffic accidents in Norway?","ar":"ما أكثر أسباب حوادث السير شيوعاً في النرويج؟","pl":"Jakie są najczęstsze przyczyny wypadków drogowych w Norwegii?"},"a":{"no":"Ifølge Statens vegvesen og Trygg Trafikk er de vanligste ulykkesårsakene: (1) For høy fart — er medvirkende i over 30% av alle dødsulykker. (2) Ruskjøring — alkohol og narkotika. (3) Tretthetskjøring — særlig stor fare for yrkessjåfører. (4) Manglende bruk av bilbelte — fordobler risikoen for å bli drept. (5) Distraksjoner — særlig mobiltelefon. (6) Feil i vegmiljøet. (7) Dårlig sikt og glatt veg.","en":"According to the Norwegian Roads Administration and Safe Traffic (Trygg Trafikk), the most common accident causes are: (1) Excessive speed — contributing to over 30% of all fatal accidents. (2) Driving under influence — alcohol and drugs. (3) Drowsy driving — especially a major risk for professional drivers. (4) Not wearing a seatbelt — doubles the risk of being killed. (5) Distractions — especially mobile phones. (6) Road environment errors. (7) Poor visibility and slippery roads.","ar":"وفقاً لإدارة الطرق العامة النرويجية وSafe Traffic، أكثر أسباب الحوادث شيوعاً: (1) السرعة الزائدة — تُسهم في أكثر من 30٪ من جميع حوادث الوفاة. (2) القيادة تحت تأثير المخدرات — كحول وعقاقير. (3) القيادة النعسانة — خطر كبير خاصةً للسائقين المهنيين. (4) عدم ارتداء حزام الأمان — يضاعف خطر الوفاة. (5) الإلهاء — خاصةً الهاتف المحمول. (6) أخطاء بيئة الطريق. (7) ضعف الرؤية وزلاقة الطريق.","pl":"Według Zarządu Dróg i Safe Traffic najczęstsze przyczyny wypadków to: (1) Nadmierna prędkość — przyczynia się do ponad 30% wszystkich śmiertelnych wypadków. (2) Jazda pod wpływem — alkohol i narkotyki. (3) Jazda zmęczona — szczególnie duże ryzyko dla zawodowych kierowców. (4) Nieużywanie pasów — podwaja ryzyko śmierci. (5) Rozproszenie uwagi — szczególnie telefon."},"tips":{"no":"Husk: Ved 80 km/t tilsvarer 1 sekunds uoppmerksomhet 22 meter tilbakelagt strekning uten kontroll. Legg bort mobilen!","en":"Remember: At 80 km/h, 1 second of inattention equals 22 metres of distance covered without control. Put your phone away!","ar":"تذكر: عند 80 كم/ساعة، ثانية واحدة من عدم الانتباه تعادل 22 متراً من الطريق دون سيطرة. ضع هاتفك جانباً!","pl":"Pamiętaj: Przy 80 km/h 1 sekunda nieuwagi to 22 metry pokonane bez kontroli. Odłóż telefon!"},"sources":["Statens vegvesen","Trygg Trafikk","TØI Rapport 2023"]}]},{"id":"etablering","icon":"🏢","color":"#4f46e5","names":{"no":"Etablere transportselskap","en":"Setting up a transport company","ar":"إنشاء شركة نقل","pl":"Zakładanie firmy transportowej"},"intros":{"no":"Vil du starte eget transportfirma? Her er en komplett guide til hva som kreves — fra registrering og løyve til forsikring, HMS og økonomi.","en":"Want to start your own transport company? Here is a complete guide to what is required — from registration and licence to insurance, HSE and finance.","ar":"هل تريد بدء شركة نقل خاصة بك؟ إليك دليلاً شاملاً لما يُشترط — من التسجيل والرخصة إلى التأمين والسلامة المهنية والتمويل.","pl":"Chcesz założyć własną firmę transportową? Oto kompletny przewodnik — od rejestracji i licencji po ubezpieczenie, BHP i finanse."},"faqs":[{"q":{"no":"Hva er stegene for å starte et godstransportselskap i Norge?","en":"What are the steps to start a goods transport company in Norway?","ar":"ما خطوات إنشاء شركة نقل بضائع في النرويج؟","pl":"Jakie są kroki do założenia firmy transportu towarowego w Norwegii?"},"a":{"no":"For å starte lovlig godstransportvirksomhet i Norge må du: (1) Velge selskapsform (ENK, AS eller ANS). ENK er enkelt å starte, men AS gir bedre ansvarsavgrensning. (2) Registrere i Brønnøysundregistrene — gratis for ENK, 5 940 kr for AS. (3) Søke om godstransportløyve hos Statens vegvesen — dokumenter god vandel, faglig kompetanse (bestått yrkeseksamen) og finansiell kapasitet. (4) Tegne ansvarsforsikring og kaskoforsikring for kjøretøyene. (5) Sette opp HMS-system (internkontroll). (6) Sørge for at sjåfører har gyldig YSK. (7) Installere godkjent tachograf.","en":"To start a lawful goods transport business in Norway you must: (1) Choose a business form (sole trader ENK, limited company AS or partnership). ENK is easy to start but AS gives better liability limits. (2) Register with the Business Register in Brønnøysund — free for ENK, NOK 5,940 for AS. (3) Apply for a goods transport licence from the Roads Administration — document good repute, professional competence (passed vocational exam) and financial capacity. (4) Take out liability and comprehensive insurance for vehicles. (5) Set up an HSE system (internal control). (6) Ensure drivers have valid YSK. (7) Install approved tachograph.","ar":"لبدء نشاط نقل بضائع قانوني في النرويج يجب: (1) اختيار شكل الشركة (ملكية فردية ENK أو شركة مساهمة AS أو شراكة). ENK سهل البدء لكن AS يوفر حدوداً أفضل للمسؤولية. (2) التسجيل في سجل الأعمال — مجاني لـENK، 5940 كرونة لـAS. (3) التقدم لرخصة نقل بضائع من إدارة الطرق — وثّق السمعة الطيبة والكفاءة المهنية (اجتياز الامتحان المهني) والقدرة المالية. (4) الحصول على تأمين المسؤولية والتأمين الشامل للمركبات. (5) إنشاء نظام السلامة (رقابة داخلية). (6) ضمان امتلاك السائقين لـYSK صالح. (7) تركيب تاكوغراف معتمد.","pl":"Aby legalnie prowadzić firmę transportową w Norwegii: (1) Wybierz formę prawną (ENK, AS lub spółka). (2) Zarejestruj się w Rejestrze Przedsiębiorstw w Brønnøysund. (3) Złóż wniosek o licencję na transport towarowy. (4) Wykup ubezpieczenie OC i AC. (5) Ustanów system BHP. (6) Upewnij się, że kierowcy mają ważny YSK. (7) Zainstaluj atestowany tachograf."},"details":{"no":[{"title":"Finansiell kapasitet","items":["Første kjøretøy: 9 000 € (ca. 100 000 kr)","Hvert ekstra kjøretøy: 5 000 € (ca. 55 000 kr)","Dokumenteres med bankgaranti, balanse eller forsikring","Gjelder ikke for nasjonalt varebilløyve"]},{"title":"Faglig kompetanse","items":["Yrkeseksamen hos Statens vegvesen","5 fagomrader: økonomi, jus, forretningsledelse, teknisk, trafikksikkerhet","Kan unntas hvis du ansetter transportleder med eksamen","Eksamen dekker EU-forordningene 1071/2009"]}]},"sources":["EU-forordning 1071/2009","Yrkestransportlova §§ 4-7","Brønnøysundregistrene","Statens vegvesen"]}]},{"id":"kjoretoy_teknikk","icon":"🔧","color":"#7c3aed","names":{"no":"Kjøretøyteknikk","en":"Vehicle technology","ar":"تقنيات المركبات","pl":"Technika pojazdu"},"intros":{"no":"Kunnskap om kjøretøyteknikk er avgjørende for sikker kjøring og forebygging av ulykker. Sjåfører plikter å sjekke kjøretøyet før bruk.","en":"Knowledge of vehicle technology is essential for safe driving and accident prevention. Drivers are required to check the vehicle before use.","ar":"معرفة تقنيات المركبات ضرورية للقيادة الآمنة والوقاية من الحوادث. يُلزم السائقون بفحص المركبة قبل الاستخدام.","pl":"Wiedza o technice pojazdu jest niezbędna do bezpiecznej jazdy. Kierowcy są zobowiązani do sprawdzenia pojazdu przed użyciem."},"faqs":[{"q":{"no":"Hva skal sjåfør kontrollere før kjøring?","en":"What should the driver check before driving?","ar":"ماذا يجب على السائق فحصه قبل القيادة؟","pl":"Co powinien sprawdzić kierowca przed jazdą?"},"a":{"no":"Daglig kjøretøykontroll er en plikt for yrkessjåfører etter vtrl. § 23. Sjekklisten bør inkludere: (1) Dekk — lufttrykk, slitasje (min. 3 mm vinterdekk, 1,6 mm sommer), sprekker og skader. (2) Bremser — prøvebremse, bremseluft (trykkluftbremser). (3) Lys — alle lys fungerer. (4) Speil og vinduer — fri sikt. (5) Lykter og varsellys i dashbord. (6) Motorolje, kjølevæske, bremsevæske. (7) Lastsikring — stropper og surringer korrekt. (8) Dokumenter — løyvekort, kjøreseddel, tachografkort.","en":"Daily vehicle inspection is a duty for professional drivers under Road Traffic Act §23. The checklist should include: (1) Tyres — air pressure, tread (min. 3mm winter, 1.6mm summer), cracks and damage. (2) Brakes — test braking, air pressure (air brakes). (3) Lights — all lights working. (4) Mirrors and windows — clear view. (5) Dashboard warning lights. (6) Engine oil, coolant, brake fluid. (7) Load securing — straps and lashings correct. (8) Documents — licence card, driver's permit, tachograph card.","ar":"الفحص اليومي للمركبة واجب على السائقين المهنيين بموجب المادة 23 من قانون السير. تشمل القائمة: (1) الإطارات — ضغط الهواء والتآكل (الحد الأدنى 3 مم شتاء، 1.6 مم صيف) والشقوق والأضرار. (2) الفرامل — فرملة تجريبية وضغط هواء. (3) الأضواء — جميع الأضواء تعمل. (4) المرايا والنوافذ — رؤية واضحة. (5) أضواء التحذير في لوحة القيادة. (6) زيت المحرك وسائل التبريد وسائل الفرامل. (7) تأمين الحمولة. (8) الوثائق.","pl":"Codzienna kontrola pojazdu jest obowiązkiem zawodowych kierowców. Lista kontrolna powinna obejmować: (1) Opony — ciśnienie, bieżnik, uszkodzenia. (2) Hamulce. (3) Światła. (4) Lusterka i szyby. (5) Kontrolki na desce rozdzielczej. (6) Olej silnikowy, płyn chłodzący, płyn hamulcowy. (7) Zabezpieczenie ładunku. (8) Dokumenty."},"tips":{"no":"Huskeliste EU-kontroll: EU-kontroll (periodisk kjøretøykontroll) gjennomføres hvert 2. år for personbiler og hvert år for tyngre kjøretøy og taxier. Bestill i god tid — feil kan kreve reparasjon og ny kontroll.","en":"MOT checklist: The MOT (periodic vehicle inspection) is carried out every 2 years for private cars and annually for heavier vehicles and taxis. Book well in advance — defects may require repair and re-inspection.","ar":"قائمة التحقق من الفحص الدوري: يُجرى الفحص الدوري للسيارة كل سنتين للسيارات الخاصة وسنوياً للمركبات الثقيلة والتاكسي. احجز مبكراً — الأعطال قد تستلزم الإصلاح وإعادة الفحص.","pl":"Lista kontrolna przeglądu: Przegląd techniczny jest przeprowadzany co 2 lata dla samochodów osobowych i corocznie dla cięższych pojazdów i taksówek."},"sources":["Vegtrafikkloven § 23","Kjøretøyforskriften","EU-kontrollforskriften"]}]},{"id":"lover_regler","icon":"⚖️","color":"#0891b2","names":{"no":"Lover og regelverk","en":"Laws and regulations","ar":"القوانين والأنظمة","pl":"Przepisy prawa"},"intros":{"no":"Transportnæringen er regulert av et komplekst regelverk — fra norsk vegtrafikkloven til EU-forordninger. Her er de viktigste lovene du må kjenne.","en":"The transport industry is regulated by a complex framework — from Norwegian road traffic law to EU regulations. Here are the most important laws you must know.","ar":"قطاع النقل منظم بإطار تشريعي معقد — من قانون السير النرويجي إلى لوائح الاتحاد الأوروبي. إليك أهم القوانين التي يجب معرفتها.","pl":"Branża transportowa jest regulowana przez złożone przepisy — od norweskiego prawa drogowego do rozporządzeń UE. Oto najważniejsze przepisy, które musisz znać."},"faqs":[{"q":{"no":"Hva er de viktigste lovene for transportnæringen?","en":"What are the most important laws for the transport industry?","ar":"ما أهم القوانين لقطاع النقل؟","pl":"Jakie są najważniejsze przepisy dla branży transportowej?"},"a":{"no":"Transportnæringen reguleres av mange lover og forskrifter. De viktigste er: (1) Vegtrafikkloven (vtrl.) — grunnloven for alle som ferdes på veg i Norge. Regulerer fartsgrenser, vikeplikt, bilbelte, ruspåvirket kjøring, ansvarsforhold. (2) Yrkestransportlova — regulerer løyvekrav, vandel, faglig kompetanse og finansiell kapasitet for yrkestransport. (3) Arbeidsmiljøloven (aml.) — arbeidstakers rettigheter og arbeidsgivers plikter. Inkludert arbeidstid, ferie, vern mot oppsigelse. (4) EU-forordning 561/2006 — kjøre- og hviletid. (5) EU-forordning 165/2014 — tachograf. (6) EU-forordning 1071/2009 — adgang til yrket. (7) EU-forordning 1072/2009 — godstransport. (8) ADR-forskriften — farlig gods.","en":"The transport industry is regulated by many laws and regulations. The most important are: (1) Road Traffic Act — the basic law for all road users in Norway. Regulates speed limits, right of way, seatbelts, drink driving, liability. (2) Transport Act — regulates licence requirements, repute, professional competence and financial capacity for commercial transport. (3) Working Environment Act — employees' rights and employers' obligations. Including working hours, holidays, protection against dismissal. (4) EU Regulation 561/2006 — driving and rest times. (5) EU Regulation 165/2014 — tachograph. (6) EU Regulation 1071/2009 — access to the profession. (7) EU Regulation 1072/2009 — goods transport. (8) ADR regulations — dangerous goods.","ar":"يُنظّم قطاع النقل بقوانين ولوائح عديدة. أهمها: (1) قانون السير — القانون الأساسي لجميع مستخدمي الطريق في النرويج. ينظم حدود السرعة والأولوية وأحزمة الأمان والقيادة تحت تأثير الكحول والمسؤولية. (2) قانون النقل المهني — ينظم اشتراطات الرخصة والسمعة الكفاءة المهنية والقدرة المالية. (3) قانون بيئة العمل — حقوق الموظفين والتزامات أصحاب العمل. (4) لائحة 561/2006 — أوقات القيادة والراحة. (5) لائحة 165/2014 — التاكوغراف. (6) لائحة 1071/2009 — الوصول للمهنة. (7) لائحة 1072/2009 — نقل البضائع. (8) لوائح ADR — البضائع الخطرة.","pl":"Branżę transportową reguluje wiele przepisów. Najważniejsze to: (1) Kodeks drogowy. (2) Ustawa o transporcie zawodowym. (3) Ustawa o środowisku pracy. (4) Rozporządzenie UE 561/2006 — czas jazdy i odpoczynku. (5) Rozporządzenie UE 165/2014 — tachograf. (6) Rozporządzenie UE 1071/2009 — dostęp do zawodu. (7) Rozporządzenie UE 1072/2009 — transport towarowy. (8) Przepisy ADR."},"tips":{"no":"Alle norske lover og forskrifter er tilgjengelig gratis på lovdata.no. EU-forordninger er direkte tilgjengelig på eur-lex.europa.eu.","en":"All Norwegian laws and regulations are available free at lovdata.no. EU regulations are directly available at eur-lex.europa.eu.","ar":"جميع القوانين والأنظمة النرويجية متاحة مجاناً على lovdata.no. لوائح الاتحاد الأوروبي متاحة مباشرةً على eur-lex.europa.eu.","pl":"Wszystkie norweskie przepisy są dostępne bezpłatnie na lovdata.no. Rozporządzenia UE są dostępne na eur-lex.europa.eu."},"sources":["Lovdata.no","EUR-Lex","Statens vegvesen"]}]},{"id":"digital_teknologi","icon":"💻","color":"#06b6d4","names":{"no":"Digital teknologi i transport","en":"Digital technology in transport","ar":"التكنولوجيا الرقمية في النقل","pl":"Technologia cyfrowa w transporcie"},"intros":{"no":"Digitalisering forandrer transportsektoren raskt. Fra GPS-sporing og flåtestyring til elektriske lastebiler og AI-optimalisert logistikk.","en":"Digitalisation is rapidly changing the transport sector. From GPS tracking and fleet management to electric lorries and AI-optimised logistics.","ar":"الرقمنة تغيّر قطاع النقل بسرعة. من تتبع GPS وإدارة الأسطول إلى الشاحنات الكهربائية والخدمات اللوجستية المُحسّنة بالذكاء الاصطناعي.","pl":"Cyfryzacja szybko zmienia sektor transportowy. Od śledzenia GPS i zarządzania flotą po elektryczne ciężarówki i logistykę optymalizowaną przez AI."},"faqs":[{"q":{"no":"Hva er fordelene med digitale transportløsninger?","en":"What are the benefits of digital transport solutions?","ar":"ما فوائد الحلول الرقمية للنقل؟","pl":"Jakie są korzyści z cyfrowych rozwiązań transportowych?"},"a":{"no":"Digitale transportløsninger gir en rekke fordeler: (1) GPS-sporing — sanntidsposisjon på alle kjøretøy gir bedre kundekommunikasjon og raskere respons ved avvik. (2) Tachografdata — digital nedlasting og analyse av sjåføratferd og kjøretid. (3) Ruteoptimalisering — AI beregner beste rute basert på trafikk, vekt og kjøretidsbegrensninger. (4) Elektroniske fraktbrev (eCMR) — erstatter papirbrev og reduserer feil. (5) Vedlikeholdsplanlegging — OBD-data forutsier feil før de oppstår. (6) Flåtestyring — én overordnet oversikt over alle kjøretøy, sjåfører og oppdrag.","en":"Digital transport solutions offer numerous benefits: (1) GPS tracking — real-time position on all vehicles gives better customer communication and faster response to deviations. (2) Tachograph data — digital download and analysis of driver behaviour and driving time. (3) Route optimisation — AI calculates the best route based on traffic, weight and driving time restrictions. (4) Electronic consignment notes (eCMR) — replaces paper notes and reduces errors. (5) Maintenance planning — OBD data predicts faults before they occur. (6) Fleet management — one overall overview of all vehicles, drivers and jobs.","ar":"الحلول الرقمية للنقل توفر فوائد عديدة: (1) تتبع GPS — الموقع في الوقت الحقيقي لجميع المركبات. (2) بيانات التاكوغراف — تنزيل رقمي وتحليل لسلوك السائق. (3) تحسين المسار — الذكاء الاصطناعي يحسب أفضل مسار. (4) بوالص الشحن الإلكترونية (eCMR). (5) تخطيط الصيانة — بيانات OBD. (6) إدارة الأسطول.","pl":"Cyfrowe rozwiązania transportowe oferują wiele korzyści: (1) Śledzenie GPS. (2) Dane tachografu. (3) Optymalizacja tras. (4) Elektroniczne listy przewozowe (eCMR). (5) Planowanie konserwacji. (6) Zarządzanie flotą."},"tips":{"no":"El-lastebiler: Norge er et foregangsland for elektriske lastebiler. Volvo, Mercedes, DAF og MAN har nå elektriske modeller med rekkevidde på 200–400 km — godt nok for bydistribusjon og regionale oppdrag.","en":"Electric lorries: Norway is a pioneer for electric lorries. Volvo, Mercedes, DAF and MAN now have electric models with a range of 200-400 km — sufficient for city distribution and regional jobs.","ar":"الشاحنات الكهربائية: النرويج رائدة في الشاحنات الكهربائية. Volvo وMercedes وDAF وMAN لديهم الآن نماذج كهربائية بمدى 200-400 كم.","pl":"Elektryczne ciężarówki: Norwegia jest pionierem w zakresie elektrycznych ciężarówek. Volvo, Mercedes, DAF i MAN mają teraz modele elektryczne z zasięgiem 200-400 km."},"sources":["Transportøkonomisk institutt (TØI)","Statens vegvesen","European Commission Digital Transport"]}]}];
